//
//	x     y     IEEE  AMD64
//	----- ----- ----- -----
//	NaN   y     NaN   y
//	x     NaN   NaN   NaN
//	-Inf  y     y     y
//	x     -Inf  x     x
//	+Inf  y     +Inf  +Inf
